def cl(f):
 if f['ns']<=16:return 'малые ≤16'
 if f['workers_per_skill_office']<.35 or f['unservable_fraction']>.1:return 'дефицит навыков'
 if f['geo_distance_corr']<-.5:return 'расстояния против геометрии'
 if f['ns']>=4096:return 'крупные ≥4096'
 if f['count_slack']<=.1 and f['balance_pressure']>=.2:return 'тесный count/load баланс'
 if f['geo_distance_corr']<.95:return 'нерегулярные расстояния'
 return 'прочие'
def link(path,label):return f'[{label}]({ROOT/path})'
